INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Sicherheitsbewertung nur die Vertraulichkeit von Daten prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Integrität und Verfügbarkeit werden bewertet"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird primär für die Bewertung des Schutzbedarfs genutzt?', 3, '[{"text": "Vertraulichkeit", "correct": true, "because": "Kern der Datensicherheit"}, {"text": "Dateigröße", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Netzwerkbandbreite", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der Sicherheitsbewertung betrachtet?', 5, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schützt sensible Daten"}, {"text": "Integrität", "correct": true, "because": "Sichert Datenkorrektheit"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Sicherheitsaspekt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verfügbarkeit ist ein Schutzbedarfskriterium. b) Es wird immer ignoriert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Verfügbarkeit ist zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bewertung des Schutzbedarfs?', 4, '[{"text": "Schadenspotenzial", "correct": false, "because": "Bestimmt Risiko"}, {"text": "Systemkritikalität", "correct": false, "because": "Beeinflusst Priorität"}, {"text": "Serverdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bewertung einmalig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßige Aktualisierung nötig"}, {"text": "Ja", "correct": false, "because": "Änderungen erfordern Neubewertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, den Schutzbedarf systematisch zu ermitteln?', 4, '[{"text": "Kategorisierung der Assets", "correct": true, "because": "Priorisiert Schutzobjekte"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unsicher"}, {"text": "Farbanalyse", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Bewertung nur für große Unternehmen relevant ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch KMUs brauchen Schutz"}, {"text": "Ja", "correct": false, "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüft die Bewertung nur technische Systeme?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Prozesse und Daten"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien helfen, den Schutzbedarf zu bewerten?', 5, '[{"text": "Verfügbarkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Authentizität", "correct": true, "because": "Bestätigt Identität"}, {"text": "Speicherkapazität", "correct": false, "because": "Kein Sicherheitskriterium"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse eines kritischen Systems?', 4, '[{"text": "Schadenspotenzial", "correct": true, "because": "Bestimmt Risiko"}, {"text": "Schnelle Analyse", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Designaspekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schutzbedarf wird in Kategorien eingeteilt. b) Es betrifft nur Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Assets betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Schutzbedarfsbewertung?', 3, '[{"text": "Asset-Liste", "correct": false, "because": "Definiert Schutzobjekte"}, {"text": "Risikoabschätzung", "correct": false, "because": "Bestimmt Maßnahmen"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich den Schutzbedarf eines Systems bewerte?', 4, '[{"text": "Vertraulichkeit, Integrität, Verfügbarkeit prüfen", "correct": true, "because": "Kernkriterien"}, {"text": "Nur Hardware zählen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Farben analysieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Bewertung automatisch erfolgt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Erfordert manuelle Analyse"}, {"text": "Ja", "correct": false, "because": "Expertenwissen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, den Schutzbedarf realistisch einzuschätzen?', 4, '[{"text": "Schadensszenarien bewerten", "correct": true, "because": "Zeigt Risiken"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unzuverlässig"}, {"text": "Minimale Prüfung", "correct": false, "because": "Zu oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird der Schutzbedarf nur für Daten analysiert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Systeme, Prozesse"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Sicherheitsbewertung?', 5, '[{"text": "Risikominimierung", "correct": true, "because": "Identifiziert Schwächen"}, {"text": "Priorisierung", "correct": true, "because": "Fokussiert Maßnahmen"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bewertung eines Systems unwichtig?', 3, '[{"text": "Schadenspotenzial", "correct": false, "because": "Bestimmt Risiko"}, {"text": "Systemrelevanz", "correct": false, "because": "Setzt Prioritäten"}, {"text": "Präsentationsstil", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich den Schutzbedarf eines Netzwerks ermittle?', 4, '[{"text": "Assets und Risiken analysieren", "correct": true, "because": "Liefert Grundlage"}, {"text": "Nur Firewall prüfen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Unstrukturiert"}]');
